import { Config, Effect, Layer, Schema } from "effect";
import {
  FetchHttpClient,
  HttpClient,
  HttpClientRequest,
  HttpMiddleware,
  HttpRouter,
  HttpServer,
  HttpServerRequest,
  HttpServerResponse,
} from "effect/http";
import { ServerOtlp } from "./server";

type OtlpSignal = "traces" | "metrics" | "logs";
type OtlpSignalConfig = Uppercase<OtlpSignal>;

const otlpProxyPaths = [
  "/api/otel/v1/traces",
  "/api/otel/v1/metrics",
  "/api/otel/v1/logs",
] as const;

const exporterConfig = (signal: OtlpSignalConfig) =>
  Config.Array(Schema.String, `OTEL_${signal}_EXPORTER`).pipe(
    Config.map((exporters) =>
      exporters.map((exporter) => exporter.toLowerCase().trim()),
    ),
    Config.withDefault<ReadonlyArray<string>>([]),
  );

const proxyOtlp = (baseUrl: URL, signal: OtlpSignal) =>
  Effect.gen(function* () {
    const incoming = yield* HttpServerRequest.HttpServerRequest;
    const client = yield* HttpClient.HttpClient;
    const contentType = incoming.headers["content-type"] ?? "application/json";
    const body = new Uint8Array(yield* incoming.arrayBuffer);
    const request = HttpClientRequest.get(baseUrl).pipe(
      HttpClientRequest.appendUrl(`/v1/${signal}`),
      HttpClientRequest.setMethod("POST"),
      HttpClientRequest.bodyUint8Array(body, contentType),
    );
    const upstream = yield* client.execute(request);
    const responseBody = new Uint8Array(yield* upstream.arrayBuffer);

    return HttpServerResponse.uint8Array(responseBody, {
      status: upstream.status,
      contentType: upstream.headers["content-type"],
      headers: {
        "retry-after": upstream.headers["retry-after"],
      },
    });
  }).pipe(
    Effect.withTracerEnabled(false),
    HttpMiddleware.withLoggerDisabled,
    Effect.catch((error) =>
      Effect.logError("Failed to proxy browser telemetry", error).pipe(
        Effect.as(HttpServerResponse.empty({ status: 502 })),
      ),
    ),
    Effect.provide(FetchHttpClient.layer),
  );

const otlpProxyLayer = Layer.unwrap(
  Effect.gen(function* () {
    const baseUrl = yield* Config.URL("OTEL_EXPORTER_OTLP_ENDPOINT");
    const exporters = yield* Config.all({
      logs: exporterConfig("LOGS"),
      metrics: exporterConfig("METRICS"),
      traces: exporterConfig("TRACES"),
    });

    return Layer.mergeAll(
      exporters.traces.includes("otlp")
        ? HttpRouter.add(
            "POST",
            otlpProxyPaths[0],
            proxyOtlp(baseUrl, "traces"),
          )
        : Layer.empty,
      exporters.metrics.includes("otlp")
        ? HttpRouter.add(
            "POST",
            otlpProxyPaths[1],
            proxyOtlp(baseUrl, "metrics"),
          )
        : Layer.empty,
      exporters.logs.includes("otlp")
        ? HttpRouter.add("POST", otlpProxyPaths[2], proxyOtlp(baseUrl, "logs"))
        : Layer.empty,
    );
  }),
);

const serverServices = HttpServer.layerServices.pipe(
  Layer.provideMerge(HttpMiddleware.layerTracerDisabledForUrls(otlpProxyPaths)),
);

export class HttpApiOtlp {
  static readonly layer = Layer.mergeAll(
    ServerOtlp.layer,
    otlpProxyLayer,
    serverServices,
  );
}

import {
  Context,
  Effect,
  FiberSet,
  Layer,
  Predicate,
  Ref,
  References,
  Schema,
  Stream,
} from "effect";
import { FetchHttpClient, HttpClientRequest } from "effect/http";
import {
  type Otlp,
  OtlpExporter,
  OtlpLogger,
  OtlpMetrics,
  OtlpSerialization,
  OtlpTracer,
} from "effect/observability";

import { OtlpEvents, track, type EventExportOptions } from "./events";
import {
  BrowserIdentity,
  PageEvent,
  type EventAttributes,
  type EventOptions,
  type PageOptions,
} from "./schema";

export type {
  BrowserIdentity,
  EventAttributes,
  EventOptions,
  PageOptions,
} from "./schema";

class BrowserIdentityState extends Context.Service<
  BrowserIdentityState,
  Ref.Ref<BrowserIdentity>
>()("krakstack/opentelemetry/BrowserIdentity") {
  static readonly layer = Layer.effect(this, Ref.make<BrowserIdentity>({}));
}

class BrowserReportedError extends Schema.TaggedError<BrowserReportedError>()(
  "BrowserReportedError",
  {
    type: Schema.Literals(["window.error", "unhandledrejection"]),
    message: Schema.String,
    stack: Schema.optional(Schema.String),
  },
) {}

const reportBrowserException = (exception: BrowserReportedError) =>
  Effect.fail(exception).pipe(
    Effect.withSpan("browser.exception", {
      root: true,
      sampled: true,
      attributes: {
        "exception.type": exception.type,
        "exception.message": exception.message,
        "exception.stacktrace": exception.stack ?? "",
      },
    }),
    Effect.ignoreCause,
  );

const BrowserExceptionTrackingLive = Layer.effectDiscard(
  Stream.merge(
    Stream.fromEventListener<ErrorEvent>(globalThis, "error", {
      bufferSize: 100,
    }).pipe(
      Stream.map((event) => {
        const error: unknown = event.error;
        return new BrowserReportedError({
          type: "window.error",
          message: event.message,
          stack: Predicate.isError(error) ? error.stack : undefined,
        });
      }),
    ),
    Stream.fromEventListener<PromiseRejectionEvent>(
      globalThis,
      "unhandledrejection",
      { bufferSize: 100 },
    ).pipe(
      Stream.map((event) => {
        const reason: unknown = event.reason;
        return new BrowserReportedError(
          Predicate.isError(reason)
            ? {
                type: "unhandledrejection",
                message: reason.message,
                stack: reason.stack,
              }
            : {
                type: "unhandledrejection",
                message: "Unhandled promise rejection",
              },
        );
      }),
    ),
  ).pipe(Stream.runForEach(reportBrowserException), Effect.forkScoped),
);

const BrowserLifecycleFlushingLive = Layer.effectDiscard(
  Effect.gen(function* () {
    const flusher = yield* OtlpExporter.Flusher;
    const fibers = yield* FiberSet.make();
    const run = yield* FiberSet.runtime(fibers)();
    const flush = () => {
      run(
        flusher.flush.pipe(
          Effect.provideService(FetchHttpClient.RequestInit, {
            keepalive: true,
          }),
        ),
      );
    };
    const onVisibilityChange = () => {
      if (document.visibilityState === "hidden") flush();
    };

    yield* Effect.acquireRelease(
      Effect.sync(() => {
        document.addEventListener("visibilitychange", onVisibilityChange);
        globalThis.addEventListener("pagehide", flush);
      }),
      () =>
        Effect.sync(() => {
          document.removeEventListener("visibilitychange", onVisibilityChange);
          globalThis.removeEventListener("pagehide", flush);
        }),
    );
  }),
);

type OtlpOptions = Parameters<typeof Otlp.layerJson>[0];

type SignalOptions<Options> = Omit<Options, "url" | "resource" | "headers">;

export interface BrowserOtlpOptions {
  readonly serviceName: string;
  readonly serviceVersion?: string;
  readonly attributes?: NonNullable<OtlpOptions["resource"]>["attributes"];
  readonly baseUrl?: string;
  readonly headers?: OtlpOptions["headers"];
  readonly traces?:
    | false
    | SignalOptions<Parameters<typeof OtlpTracer.layer>[0]>;
  readonly metrics?:
    | false
    | SignalOptions<Parameters<typeof OtlpMetrics.layer>[0]>;
  readonly logs?: false | SignalOptions<Parameters<typeof OtlpLogger.layer>[0]>;
  readonly events?:
    | false
    | (EventExportOptions & {
        /** Initial page and pathname changes; enabled by default. */
        readonly pageViews?: boolean;
      });
}

const browserEffects = {
  /** Replaces identity for future events in this runtime; does not persist or emit an event. */
  identify: Effect.fnUntraced(function* (input: BrowserIdentity) {
    const identity = yield* Schema.decodeUnknownEffect(BrowserIdentity)(input);
    const state = yield* BrowserIdentityState;
    yield* Ref.set(state, identity);
  }),

  reset: Effect.gen(function* () {
    const state = yield* BrowserIdentityState;
    yield* Ref.set(state, {});
  }),

  track: Effect.fnUntraced(function* (
    name: string,
    properties?: EventAttributes,
    options?: EventOptions,
  ) {
    const state = yield* BrowserIdentityState;
    const identity = yield* Ref.get(state);
    const annotations: Record<string, string> = {};
    if (identity.userId) annotations["user.id"] = identity.userId;
    if (identity.organizationId)
      annotations["organization.id"] = identity.organizationId;
    const scoped = yield* References.CurrentLogAnnotations;
    yield* track(name, properties, options).pipe(
      Effect.annotateLogs({ ...annotations, ...scoped }),
    );
  }),

  /** Call on initial render and completed SPA navigations; no identifiers are persisted. */
  page: Effect.fnUntraced(function* (
    input: PageOptions = {},
  ): Effect.fn.Return<
    void,
    Schema.SchemaError,
    BrowserIdentityState | OtlpEvents
  > {
    const page = yield* Schema.decodeUnknownEffect(PageEvent)(input);
    const properties = { ...page.properties };
    if (page.name) properties["analytics.page.name"] = page.name;
    if (page.category) properties["analytics.page.category"] = page.category;
    properties["url.path"] =
      (page.path ?? globalThis.location.pathname).split(/[?#]/, 1)[0] ?? "/";
    yield* browserEffects.track("browser.page_view", properties, page.options);
  }),
};

type BrowserProgram = Effect.Effect<
  void,
  Schema.SchemaError,
  BrowserIdentityState | OtlpEvents
>;
interface BrowserClient {
  readonly identity: Ref.Ref<BrowserIdentity>;
  readonly events: OtlpEvents["Service"];
}
const browserClients: Array<BrowserClient> = [];
const runBrowser = (
  program: BrowserProgram,
): Effect.Effect<void, Schema.SchemaError> =>
  Effect.suspend(() => {
    const client = browserClients.at(-1);
    if (!client) return Effect.void;
    return program.pipe(
      Effect.provideService(BrowserIdentityState, client.identity),
      Effect.provideService(OtlpEvents, client.events),
    );
  });

const BrowserClientLive = Layer.effectDiscard(
  Effect.gen(function* () {
    const identity = yield* BrowserIdentityState;
    const events = yield* OtlpEvents;
    yield* Effect.acquireRelease(
      Effect.sync(() => {
        const client = { identity, events };
        browserClients.push(client);
        return client;
      }),
      (client) =>
        Effect.sync(() => {
          const index = browserClients.indexOf(client);
          if (index !== -1) browserClients.splice(index, 1);
        }),
    );
  }),
);

const pageViewListeners = new Set<() => void>();
let stopPageViewTracking: (() => void) | undefined;

const subscribePageViews = (listener: () => void) => {
  if (pageViewListeners.size === 0) {
    const history = globalThis.history;
    const pushState = history.pushState;
    const replaceState = history.replaceState;
    const notify = () => {
      for (const onPage of pageViewListeners) onPage();
    };
    const trackedPushState: History["pushState"] = (...args) => {
      pushState.apply(history, args);
      notify();
    };
    const trackedReplaceState: History["replaceState"] = (...args) => {
      replaceState.apply(history, args);
      notify();
    };
    history.pushState = trackedPushState;
    history.replaceState = trackedReplaceState;
    globalThis.addEventListener("popstate", notify);
    stopPageViewTracking = () => {
      globalThis.removeEventListener("popstate", notify);
      if (history.pushState === trackedPushState) history.pushState = pushState;
      if (history.replaceState === trackedReplaceState)
        history.replaceState = replaceState;
    };
  }
  pageViewListeners.add(listener);
  return () => {
    pageViewListeners.delete(listener);
    if (pageViewListeners.size === 0) {
      stopPageViewTracking?.();
      stopPageViewTracking = undefined;
    }
  };
};

const BrowserPageViewsLive = Layer.effectDiscard(
  Effect.gen(function* () {
    const fibers = yield* FiberSet.make();
    const run = yield* FiberSet.runtime(fibers)<
      BrowserIdentityState | OtlpEvents
    >();
    let previousPath = globalThis.location.pathname;
    yield* Effect.acquireRelease(
      Effect.sync(() =>
        subscribePageViews(() => {
          const path = globalThis.location.pathname;
          if (path === previousPath) return;
          previousPath = path;
          run(browserEffects.page({ path }).pipe(Effect.ignore));
        }),
      ),
      (unsubscribe) => Effect.sync(unsubscribe),
    );
    yield* browserEffects.page({ path: previousPath }).pipe(Effect.ignore);
  }),
);

export class BrowserOtlp {
  /** Effects use the active browser layer without requiring its services in the calling runtime. */
  static readonly identify = (identity: BrowserIdentity) =>
    runBrowser(browserEffects.identify(identity));
  static readonly reset = runBrowser(browserEffects.reset);
  static readonly track = (
    name: string,
    properties?: EventAttributes,
    options?: EventOptions,
  ) => runBrowser(browserEffects.track(name, properties, options));
  static readonly page = (options?: PageOptions) =>
    runBrowser(browserEffects.page(options));

  static readonly pageView = BrowserOtlp.page;

  static readonly layer = ({
    attributes,
    baseUrl = "/api/otel",
    logs = false,
    events = false,
    metrics = false,
    serviceName,
    serviceVersion,
    traces = {},
    headers,
  }: BrowserOtlpOptions) => {
    const { pageViews = true, ...eventOptions } =
      events === false ? {} : events;
    const resource = { attributes, serviceName, serviceVersion };
    const request = HttpClientRequest.get(baseUrl);
    const signalUrl = (signal: "logs" | "metrics" | "traces") =>
      HttpClientRequest.appendUrl(request, `/v1/${signal}`).url;
    const exporters = Layer.mergeAll(
      OtlpExporter.layerFlusher,
      events !== false
        ? OtlpEvents.layer({
            exportInterval: "30 seconds",
            maxBatchSize: 100,
            shutdownTimeout: "3 seconds",
            ...eventOptions,
            url: signalUrl("logs"),
            resource,
            headers,
          })
        : OtlpEvents.disabledLayer,
      traces !== false
        ? OtlpTracer.layer({
            exportInterval: "30 seconds",
            ...traces,
            url: signalUrl("traces"),
            resource,
            headers,
          })
        : Layer.empty,
      metrics !== false
        ? OtlpMetrics.layer({
            exportInterval: "60 seconds",
            ...metrics,
            url: signalUrl("metrics"),
            resource,
            headers,
          })
        : Layer.empty,
      logs !== false
        ? OtlpLogger.layer({
            excludeLogSpans: true,
            mergeWithExisting: true,
            ...logs,
            url: signalUrl("logs"),
            resource,
            headers,
          })
        : Layer.empty,
    ).pipe(
      Layer.provideMerge(OtlpExporter.layerFlusher),
      Layer.provide(OtlpSerialization.layerJson),
      Layer.provide(FetchHttpClient.layer),
    );

    return Layer.mergeAll(
      BrowserClientLive,
      BrowserLifecycleFlushingLive,
      events !== false && pageViews ? BrowserPageViewsLive : Layer.empty,
      traces !== false ? BrowserExceptionTrackingLive : Layer.empty,
    ).pipe(
      Layer.provideMerge(Layer.merge(BrowserIdentityState.layer, exporters)),
    );
  };
}

import { Config, Effect, Layer, Schema } from "effect";
import { FetchHttpClient } from "effect/http";
import { Otlp, OtlpExporter, OtlpSerialization } from "effect/observability";

import { OtlpEvents, track } from "./events";

export type { EventAttributes, EventOptions } from "./schema";

const ServerEventsLive = Layer.unwrap(
  Effect.gen(function* () {
    const disabled = yield* Config.Boolean("OTEL_SDK_DISABLED").pipe(
      Config.withDefault(false),
    );
    const exporters = yield* Config.Array(
      Schema.String,
      "OTEL_LOGS_EXPORTER",
    ).pipe(Config.withDefault<ReadonlyArray<string>>([]));
    if (
      disabled ||
      !exporters.some((value) => value.trim().toLowerCase() === "otlp")
    ) {
      return OtlpEvents.disabledLayer;
    }
    const endpoint = yield* Config.URL("OTEL_EXPORTER_OTLP_LOGS_ENDPOINT").pipe(
      Config.orElse(() =>
        Config.URL("OTEL_EXPORTER_OTLP_ENDPOINT").pipe(
          Config.map((url) => {
            url.pathname += `${url.pathname.endsWith("/") ? "" : "/"}v1/logs`;
            return url;
          }),
        ),
      ),
      Config.withDefault(undefined),
    );
    if (!endpoint) {
      return OtlpEvents.disabledLayer;
    }
    const headersConfig = (name: string) =>
      Config.Record(Schema.String, Schema.StringFromUriComponent, name);
    const headers = yield* headersConfig(
      "OTEL_EXPORTER_OTLP_LOGS_HEADERS",
    ).pipe(
      Config.orElse(() => headersConfig("OTEL_EXPORTER_OTLP_HEADERS")),
      Config.withDefault(undefined),
    );
    return OtlpEvents.layer({
      url: endpoint.toString(),
      headers,
      exportInterval: "1 second",
      maxBatchSize: 1000,
      shutdownTimeout: "3 seconds",
    });
  }).pipe(Effect.orDie),
);

/** Runtime-neutral server telemetry for HTTP applications, workers, and CLIs. */
export class ServerOtlp {
  static readonly track = track;

  static readonly layer = Layer.mergeAll(
    Otlp.layerFromConfig(),
    ServerEventsLive,
  ).pipe(
    Layer.provideMerge(OtlpExporter.layerFlusher),
    Layer.provide(OtlpSerialization.layerJson),
    Layer.provide(FetchHttpClient.layer),
  );
}

import {
  Clock,
  Context,
  DateTime,
  Effect,
  Layer,
  Option,
  References,
  Schema,
} from "effect";
import {
  OtlpExporter,
  OtlpResource,
  OtlpSerialization,
} from "effect/observability";

import {
  TelemetryEvent,
  type EventAttributes,
  type EventOptions,
} from "./schema";

type ExporterOptions = Pick<
  Parameters<typeof OtlpExporter.make>[0],
  "url" | "headers" | "exportInterval" | "maxBatchSize" | "shutdownTimeout"
> & {
  readonly resource?: Parameters<typeof OtlpResource.fromConfig>[0];
};

export type EventExportOptions = Partial<
  Pick<ExporterOptions, "exportInterval" | "maxBatchSize" | "shutdownTimeout">
>;

export class OtlpEvents extends Context.Service<
  OtlpEvents,
  { readonly push: (record: EventRecord) => void }
>()("krakstack/opentelemetry/Events") {
  static readonly disabledLayer = Layer.succeed(this, { push: () => {} });

  static readonly layer = (options: ExporterOptions) =>
    Layer.effect(
      this,
      Effect.gen(function* () {
        const serialization = yield* OtlpSerialization.OtlpSerialization;
        const resource = yield* OtlpResource.fromConfig(options.resource);
        return yield* OtlpExporter.make({
          ...options,
          label: "OtlpEvents",
          body: (logRecords) => [
            serialization.logs({
              resourceLogs: [
                {
                  resource,
                  scopeLogs: [
                    {
                      scope: { name: "krakstack.events" },
                      logRecords,
                    },
                  ],
                },
              ],
            }),
            Effect.void,
          ],
        });
      }),
    );
}

interface EventRecord {
  readonly eventName: string;
  readonly timeUnixNano: string;
  readonly observedTimeUnixNano: string;
  readonly severityNumber: 9;
  readonly attributes: ReturnType<typeof OtlpResource.entriesToAttributes>;
  readonly droppedAttributesCount: 0;
  readonly traceId?: string;
  readonly spanId?: string;
}

/** Emits an INFO event without creating a tracing span or persisting identity. */
export const track = Effect.fnUntraced(function* (
  name: string,
  properties?: EventAttributes,
  options?: EventOptions,
) {
  const event = yield* Schema.decodeUnknownEffect(TelemetryEvent)({
    name,
    properties,
    options,
  });
  const events = yield* OtlpEvents;
  const clock = yield* Clock.Clock;
  const observedTime = clock.currentTimeNanosUnsafe().toString();
  const timestamp = event.options?.timestamp
    ? (
        BigInt(DateTime.toEpochMillis(event.options.timestamp)) * 1_000_000n
      ).toString()
    : observedTime;
  const span = yield* Effect.currentSpan.pipe(Effect.option);
  const attributes = { ...event.options?.context, ...event.properties };
  if (event.options?.userId) attributes["user.id"] = event.options.userId;
  if (event.options?.anonymousId)
    attributes["analytics.anonymous_id"] = event.options.anonymousId;
  if (event.options?.sessionId)
    attributes["session.id"] = event.options.sessionId;
  if (event.options?.messageId)
    attributes["log.record.uid"] = event.options.messageId;
  const annotations = yield* References.CurrentLogAnnotations;
  events.push({
    eventName: event.name,
    timeUnixNano: timestamp,
    observedTimeUnixNano: observedTime,
    severityNumber: 9,
    attributes: OtlpResource.entriesToAttributes(
      Object.entries({
        ...attributes,
        ...annotations,
      }),
    ),
    droppedAttributesCount: 0,
    traceId: Option.isSome(span) ? span.value.traceId : undefined,
    spanId: Option.isSome(span) ? span.value.spanId : undefined,
  });
});

import { Schema } from "effect";

const EventAttributeValue = Schema.Union([
  Schema.String,
  Schema.Finite,
  Schema.Boolean,
  Schema.Array(Schema.String),
  Schema.Array(Schema.Finite),
  Schema.Array(Schema.Boolean),
]);

export const EventAttributesSchema = Schema.Record(
  Schema.String,
  EventAttributeValue,
).annotate({ identifier: "EventAttributes" });

export const EventOptionsSchema = Schema.Struct({
  userId: Schema.optional(Schema.NonEmptyString),
  anonymousId: Schema.optional(Schema.NonEmptyString),
  sessionId: Schema.optional(Schema.NonEmptyString),
  messageId: Schema.optional(Schema.NonEmptyString),
  timestamp: Schema.optional(Schema.DateTimeUtc),
  context: Schema.optional(EventAttributesSchema),
}).annotate({ identifier: "EventOptions" });

export const TelemetryEvent = Schema.Struct({
  name: Schema.NonEmptyString,
  properties: Schema.optional(EventAttributesSchema),
  options: Schema.optional(EventOptionsSchema),
}).annotate({ identifier: "TelemetryEvent" });

export const PageEvent = Schema.Struct({
  name: Schema.optional(Schema.NonEmptyString),
  category: Schema.optional(Schema.NonEmptyString),
  path: Schema.optional(Schema.NonEmptyString),
  properties: Schema.optional(EventAttributesSchema),
  options: Schema.optional(EventOptionsSchema),
}).annotate({ identifier: "PageEvent" });

export type EventAttributes = typeof EventAttributesSchema.Type;
export type EventOptions = typeof EventOptionsSchema.Type;
export type PageOptions = typeof PageEvent.Type;

export const BrowserIdentity = Schema.Struct({
  userId: Schema.optional(Schema.NonEmptyString),
  organizationId: Schema.optional(Schema.NonEmptyString),
}).annotate({ identifier: "BrowserTelemetryIdentity" });

export type BrowserIdentity = typeof BrowserIdentity.Type;

docs:
## Overview

`ServerOtlp` in `services/opentelemetry/server.ts` provides exporters and named events for servers, workers, and CLIs. `BrowserOtlp` in `browser.ts` provides browser exporters, exception capture, automatic page views, custom events, and in-memory identity. `HttpApiOtlp` in `api.ts` composes `ServerOtlp.layer` with same-origin OTLP proxy routes and HTTP services.

## Server

Provide `ServerOtlp.layer` to a long-lived runtime, or `HttpApiOtlp.layer` to HTTP routes; the latter already includes the former. Dispose the runtime on shutdown to flush pending data.

```ts
import { Effect } from "effect";
import { ServerOtlp } from "@/services/opentelemetry/server";

const program = ServerOtlp.track("app.order.completed", { "order.total": 49 })
  .pipe(Effect.provide(ServerOtlp.layer));
```

Server events follow `OTEL_LOGS_EXPORTER=otlp` and `OTEL_SDK_DISABLED`. Set `OTEL_SERVICE_NAME` and `OTEL_EXPORTER_OTLP_ENDPOINT`; the event exporter appends `/v1/logs`. Signal-specific logs endpoint/headers override shared endpoint/headers. Resource metadata follows Effect's OTLP configuration. Events inherit scoped `Effect.annotateLogs` annotations, including AuthMiddleware's `user.id` and `organization.id`. Server identity stays fiber-scoped.

## Browser Initialization

Install once on the Atom runtime used by the API client, then mount/read its runtime atom during hydration to start the layer:

```ts
import { Atom } from "effect/reactivity";
import { BrowserOtlp } from "@/services/opentelemetry/browser";

const apiRuntime = Atom.context();
if (!import.meta.env.SSR) {
  apiRuntime.addGlobalLayer(BrowserOtlp.layer({ serviceName: "my-app-web", events: {} }));
}
```

Traces and exception capture are enabled by default; events, logs, and metrics are independently opt-in. `events: {}` enables custom events and automatic page views without application log export. Events batch every 30 seconds by default with `maxBatchSize: 100` and `shutdownTimeout: "3 seconds"`; override under `events`. The layer accepts `serviceVersion`, resource `attributes`, `baseUrl` (default `/api/otel`), and shared `headers`. Enable application logs/metrics with `logs: {}`/`metrics: {}`; `traces: false` disables browser tracing and global exception capture.

## Automatic Page Views

With events enabled, one `browser.page_view` event is recorded when the layer starts, then on each pathname change via `history.pushState`, `history.replaceState`, or `popstate` (back/forward). Same-path, query-only, and hash-only changes are ignored. History hooks/listeners are scoped and restored when the layer closes. Tracking follows URL changes, not framework loader completion. The initial page may be anonymous before identify runs; it is never retroactively rewritten. Only `url.path` is collected; path segments can still contain personal IDs.

Set `pageViews: false` to retain custom events without automatic page tracking. Use manual `page` (`pageView` alias) for route templates or application-specific timing, and avoid manually duplicating automatic views. Manual page accepts path (default `location.pathname`), name/category, properties, and common options. Query strings/fragments are stripped. Optional name/category map to `analytics.page.name`/`analytics.page.category`. These are project conventions, not standardized OTel analytics semantics.

## Identify And Track

All methods remain Effects, but use the active browser layer internally. Callers do not need its services in their own runtime:

```ts
await Effect.runPromise(BrowserOtlp.identify({ userId: "user-123", organizationId: "org-123" }));
await Effect.runPromise(BrowserOtlp.track("app.checkout.started", { "checkout.source": "cart" }));
await Effect.runPromise(BrowserOtlp.reset);
```

Calls before startup and after disposal are no-ops. If multiple layers are active, calls target the most recently started one; prefer a single browser layer. Caller trace/log context and typed validation errors are preserved.

Identify replaces user/org identity for future events; omitted fields clear previous values. Call it on auth/organization changes and reset on logout. Identity is in memory only, not localStorage/cookies. Events capture identity when recorded, so queued events are never rewritten. Identified identity overrides per-call fields; scoped log annotations take precedence. This affects events only, not automatic traces/logs, API headers, or authorization. Browser IDs are untrusted analytics metadata, not suitable for billing, audit trails, or tenant-isolated reporting. No React bridge, hook, automatic auth synchronization, profile store, or identity linking is installed.

Both environments expose `track(name, properties?, options?)`. Options include `userId`, `anonymousId`, `sessionId`, `messageId`, `timestamp` (Effect `DateTime.Utc`), and flat `context`. Properties override context; explicit options override both, mapping to `user.id`, `analytics.anonymous_id`, `session.id`, and `log.record.uid`. No IDs are generated; message IDs do not guarantee deduplication.

## Event Semantics

Following the [OTel event conventions](https://opentelemetry.io/docs/specs/semconv/general/events/), events are OTLP log records with native `eventName`, occurrence timestamp, INFO severity number 9, structured attributes, no body, and active trace/span IDs when available. No span is created. The SDK supplies observed time when recording. No clock-skew correction is performed. Use stable domain-qualified names, dynamic values in attributes, and `error.type` for failure events. Document each event's trigger and attributes. Values support strings, finite numbers, booleans, and homogeneous arrays. Invalid inputs fail with typed schema errors while the layer is active. Upstream event conventions remain in development.

## Transport

Browser signals use `/api/otel/v1/traces`, `/api/otel/v1/metrics`, and `/api/otel/v1/logs`. Corresponding `OTEL_*_EXPORTER` settings must include `otlp`. The proxy passes bytes unchanged to `OTEL_EXPORTER_OTLP_ENDPOINT` with the standard signal path, without enriching identity or forwarding session cookies. Configure collector, storage, and dashboards separately. Signal-specific server URLs do not change proxy routing.

Pending browser telemetry flushes on hidden visibility and `pagehide` with fetch keepalive. Delivery is best effort, including the browser's approximately 64 KiB aggregate keepalive budget. Apply payload/rate limits at public ingestion boundaries. Avoid sensitive attributes and high-cardinality Loki labels. Full URLs, titles, referrers, IPs, and user agents are not automatically collected.
